      config.set("compact", false);
      config.set("sortCompletedLast", false);
    },
    "2.0.19": (config) => {
      console.log("Migrating settings store from 2.0.17 → 2.0.19");
      config.set("invertTrayColor", false);
      config.set("startMinimized", false);
    },
    "2.0.26": (config) => {
      console.log("Migrating settings store from 2.0.19 → 2.0.26");
      config.delete("customStylesPath");
    },
  };


  const rerenderDefinition = {
    sorting: true,
    files: true,
    showCompleted: true,
    showHidden: true,
    fileSorting: true,
    thresholdDateInTheFuture: true,
    dueDateInTheFuture: true,
    sortCompletedLast: true,
    notificationThreshold: true,
  };


  function findChanges(oldValue, newValue) {
    const differences = {};

    for (const key in newValue) {
      if (JSON.stringify(newValue[key]) !== JSON.stringify(oldValue[key])) {
        differences[key] = {
          oldValue: oldValue[key],
          newValue: newValue[key],
        };
        if (rerenderDefinition[key]) {
          const requestedData = dataRequest(searchString);
          mainWindow!.webContents.send("requestData", requestedData);
          return false;
        }
      }
    }
    return differences;
  }


  export const SettingsStore = new Store<SettingStore>({
    cwd: userDataDirectory,
    name: "config",
    migrations,
  });


  let _filtersStore: Store | null = null;


  function getFiltersStore(): Store {
    if (!_filtersStore) {
      _filtersStore = new Store({
        cwd: userDataDirectory,
        name: "filters",
        migrations: {
          "2.0.19": (filters) => {
            console.log("Migrating filter store → 2.0.19");
            filters.set("attributes", {});
          },
        },
      });
    }
    return _filtersStore;
  }


  export const FiltersStore = {
    get: (key: string) => getFiltersStore().get(key),
    set: (key: string, value: unknown) => getFiltersStore().set(key, value),
  };


  let _colorsStore: Store | null = null;


  function getColorsStore(): Store {
    if (!_colorsStore) {
      _colorsStore = new Store({
        cwd: userDataDirectory,
        name: "colors",
        migrations: {
          "2.0.26-rc.1": (colors) => {
            console.log("Creating colors store → 2.0.26");
            colors.set("colors", colorsData);
          },
          "2.0.26": (colors) => {
            console.log(
              "Updating colors store with new selected color structures → 2.0.26",
            );
            colors.set("colors", colorsData);
          },
        },
      });
    }
    return _colorsStore;
  }


  export const ColorsStore = {
    get: (key: string) => getColorsStore().get(key),
    set: (key: string, value: unknown) => getColorsStore().set(key, value),
  };


  let _notificationsStore: Store | null = null;


  function getNotificationsStore(): Store {
    if (!_notificationsStore) {
      _notificationsStore = new Store({
        cwd: userDataDirectory,
        name: "notificationHashes",
      });
    }
    return _notificationsStore;
  }


  export const NotificationsStore = {
    get: (key: string) => getNotificationsStore().get(key),
    set: (key: string, value: unknown) => getNotificationsStore().set(key, value),
  };


  SettingsStore.onDidAnyChange((newValue, oldValue) => {
    try {
      if (mainWindow && mainWindow.webContents) {
        findChanges(oldValue, newValue);
        mainWindow.webContents.send("settingsChanged", newValue);
      } else {
        console.warn("The window is not available, skipping setting change.");
      }
    } catch (error) {
      if (error instanceof Error) HandleError(error);
    }
  });


  SettingsStore.onDidChange("files", (newValue) => {
    try {
      if (!newValue) return;

      createFileWatcher(newValue);
      UpdateTrayMenu();
    } catch (error) {
      if (error instanceof Error) HandleError(error);
    }
  });


  SettingsStore.onDidChange("colorTheme", (colorTheme) => {
    try {
      HandleTheme(colorTheme);
    } catch (error) {
      if (error instanceof Error) HandleError(error);
    }
  });


  SettingsStore.onDidChange("menuBarVisibility", (menuBarVisibility) => {
    try {
      mainWindow!.setMenuBarVisibility(menuBarVisibility!);
      mainWindow!.setAutoHideMenuBar(!menuBarVisibility);
    } catch (error) {
      if (error instanceof Error) HandleError(error);
    }
  });


  SettingsStore.onDidChange("tray", (v) => {
    try {
      if (v) CreateTray();
      else DestroyTray();
    } catch (error) {
      if (error instanceof Error) HandleError(error);
    }
  });


  SettingsStore.onDidChange("invertTrayColor", () => {
    try {
      UpdateTrayImage();
    } catch (error) {
      if (error instanceof Error) HandleError(error);
    }
  });
