content: >-
  import fs from "fs";

  import { app } from "electron";

  import { SettingsStore } from "../Stores";

  import path from "path";

  import { mainWindow } from "../index";

  import { File } from "@sleek-types";


  function readFileContent(
    filePath: string,
    bookmark: string | null = null,
  ): string {
    try {
      if (process.mas && bookmark) {
        app.startAccessingSecurityScopedResource(bookmark);
      }
      const fileContent = fs.readFileSync(filePath, "utf8");
      return fileContent;
    } catch (error) {
      throw new Error(
        `Failed to read file ${filePath}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }


  function registerTodoFile(filePath: string, bookmark: string | null) {
    if (process.mas && !bookmark) {
      mainWindow!.webContents.send(
        "responseFromMainProcess",
        "The Mac App Store release requires you to open files from within the app",
      );
      throw new Error(
        "The Mac App Store release requires you to open files from within the app",
      );
    }

    const files = SettingsStore.get("files");
    const existingFileIndex = files.findIndex(
      (file) => file.todoFilePath === filePath,
    );

    files.forEach((file) => (file.active = false));

    if (existingFileIndex === -1) {
      files.push({
        active: true,
        todoFileName: path.basename(filePath),
        todoFilePath: filePath,
        todoFileBookmark: bookmark,
        doneFilePath: null,
        doneFileBookmark: null,
      });
    } else {
      files[existingFileIndex].active = true;
    }

    SettingsStore.set("files", files);

    return "File added";
  }


  function linkDoneFile(filePath: string, bookmark: string | null) {
    const files: File[] = SettingsStore.get("files");
    const activeIndex: number = files.findIndex((file) => file.active);

    if (activeIndex === -1) return;

    files[activeIndex].doneFilePath = filePath;
    files[activeIndex].doneFileBookmark = bookmark;

    SettingsStore.set("files", files);

    mainWindow!.webContents.send("triggerArchiving", true);
  }


  function removeFile(index: number) {
    let files = SettingsStore.get("files");

    files.splice(index, 1);
    const activeIndex: number = files.findIndex((file) => file.active);

    if (files.length > 0 && activeIndex === -1) {
      files[0].active = true;
    } else if (activeIndex !== -1) {
      files[activeIndex].active = true;
    } else {
      files = [];
    }

    SettingsStore.set("files", files);

    return "File removed";
  }


  function activateFile(index: number) {
    const files: File[] = SettingsStore.get("files");

    if (files.length > 0) {
      files.forEach((file) => {
        file.active = false;
      });
    }

    files[index].active = true;

    SettingsStore.set("files", files);

    return "File changed";
  }


  export {
    activateFile,
    removeFile,
    registerTodoFile,
    linkDoneFile,
    readFileContent,
  };

