    my $state = read_state($runtime);
    if ($state && process_matches_state($state)) {
        return;
    }
    clear_state($runtime) if $state;

    my $stem = timestamp_stem($paths->{audio});
    my $wav = safe_child_path($paths->{audio}, "$stem.wav");
    my $pw_record = pw_record_binary();
    my $log_path = safe_child_path($runtime, 'whisper-record-toggle.log');

    my $pid = fork();
    defined $pid or fatal("cannot start pw-record: $!");
    if ($pid == 0) {
        open STDIN, '<', '/dev/null' or exit 127;
        open STDOUT, '>', '/dev/null' or exit 127;
        open STDERR, '>>', $log_path or exit 127;
        chmod 0600, $log_path;
        exec {
            $pw_record
        } $pw_record, '--rate=16000', '--channels=1', '--format=s16', $wav;
        exit 127;
    }

    sleep 0.1;
    my $start = proc_start_time($pid);
    if (!defined $start || !process_looks_like_pw_record($pid)) {
        kill 'TERM', $pid;
        waitpid $pid, WNOHANG;
        fatal('pw-record did not remain active after startup');
    }
    write_state($runtime, {
        pid        => "$pid",
        proc_start => "$start",
        stem       => $stem,
        wav        => $wav,
    });
}

sub wait_for_recording_exit {
    my ($state) = @_;
    for (1 .. 150) {
        return 1 unless process_matches_state($state);
        sleep 0.1;
    }
    return 0;
}

sub normalize_transcript {
    my ($text) = @_;
    $text = q{} unless defined $text;
    $text =~ s/[\p{Cc}\p{Cf}]+/ /gu;
    $text =~ s/\s+/ /gu;
    $text =~ s/\A\s+//u;
    $text =~ s/\s+\z//u;
    return $text;
}

sub transcript_from_whisper_json {
    my ($data) = @_;
    my @parts;
    if (ref $data->{transcription} eq 'ARRAY') {
        for my $segment (@{ $data->{transcription} }) {
            next unless ref $segment eq 'HASH' && defined $segment->{text};
            push @parts, $segment->{text};
        }
    } elsif (ref $data->{segments} eq 'ARRAY') {
        for my $segment (@{ $data->{segments} }) {
            next unless ref $segment eq 'HASH' && defined $segment->{text};
            push @parts, $segment->{text};
        }
    } elsif (defined $data->{text}) {
        push @parts, $data->{text};
    } elsif (ref $data->{result} eq 'HASH' && defined $data->{result}{text}) {
        push @parts, $data->{result}{text};
    }
    return normalize_transcript(join q{ }, @parts);
}

sub append_todo_entry {
    my ($sleek, $stem, $text) = @_;
    return unless length $text;
    my $lock_path = safe_child_path($sleek->{directory}, '.whisper.txt.lock');
    sysopen my $lock, $lock_path, O_CREAT | O_RDWR, 0600
        or fatal("cannot open Sleek task lock: $!");
    flock($lock, LOCK_EX)
        or fatal("cannot lock Sleek task file: $!");
    open my $fh, '>>:encoding(UTF-8)', $sleek->{task_file}
        or fatal("cannot append to Sleek task file: $!");
    my $date = substr($stem, 0, 10);
    print {$fh} "$date $text +whisper \@voice source:$stem\n"
        or fatal("cannot write Sleek task entry: $!");
    close $fh or fatal("cannot close Sleek task file: $!");
}

sub prune_timestamped_files {
    my ($directory, $extension) = @_;
    opendir my $dh, $directory
        or fatal("cannot read managed directory: $!");
    my @files = grep {
        /\A[0-9]{4}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}\.\Q$extension\E\z/
            && -f File::Spec->catfile($directory, $_)
            && !-l File::Spec->catfile($directory, $_)
    } readdir $dh;
    closedir $dh or fatal("cannot close managed directory: $!");
    @files = sort { $b cmp $a } @files;
    for my $filename (@files[$MAX_ARTIFACTS .. $#files]) {
        unlink safe_child_path($directory, $filename)
            or fatal("cannot prune managed artifact $filename: $!");
    }
}

sub transcribe_recording {
    my ($runtime, $home, $state) = @_;
    my $config = whisper_config();
    my $paths = resolved_recording_paths($home);
    my $sleek = resolved_sleek_paths($home);
    my $expected_wav = safe_child_path($paths->{audio}, "$state->{stem}.wav");
    $state->{wav} eq $expected_wav
        or fatal('runtime state recording path is outside the managed audio directory');
    -f $state->{wav} && !-l $state->{wav} && -s $state->{wav} > 44
        or fatal('recorded WAV is missing or too small to transcribe');

    my $output_prefix = safe_child_path(
        $runtime,
        ".whisper-${\$state->{stem}}-$$",
    );
    my $output_json = "$output_prefix.json";
    unlink $output_json if -e $output_json && !-l $output_json;

    my $threads = runtime_thread_count($config->{WHISPER_RUNTIME_THREADS});
    my @command = (
        $config->{WHISPER_CLI},
        '--model', $config->{WHISPER_MODEL},
        '--file', $state->{wav},
        '--threads', "$threads",
        '--output-json',
        '--no-timestamps',
        '--output-file', $output_prefix,
    );
    my $status = system { $command[0] } @command;
    if ($status != 0) {
        my $code = $status == -1 ? "exec error: $!" : "exit status " . ($status >> 8);
        fatal("whisper-cli transcription failed: $code");
    }
    -f $output_json && !-l $output_json
        or fatal('whisper-cli did not produce JSON output');

    my $parsed = read_json_object($output_json, 8 * 1024 * 1024, 'whisper-cli output');
    unlink $output_json or fatal("cannot remove transient whisper-cli JSON: $!");
    my $text = transcript_from_whisper_json($parsed);

    atomic_write_bytes(
        $paths->{transcribed},
        "$state->{stem}.json",
        encode_json({ text => $text }) . "\n",
        0600,
    );
    append_todo_entry($sleek, $state->{stem}, $text);
    prune_timestamped_files($paths->{audio}, 'wav');
    prune_timestamped_files($paths->{transcribed}, 'json');
}

sub stop_recording {
    my ($runtime, $home) = @_;
    my $state = read_state($runtime);
    return unless $state;
    if (process_matches_state($state)) {
        kill 'TERM', $state->{pid}
            or fatal("cannot stop pw-record: $!");
        wait_for_recording_exit($state)
            or fatal('pw-record did not stop within 15 seconds');
    }
    clear_state($runtime);
    transcribe_recording($runtime, $home, $state);
}

sub status_payload {
    my ($runtime) = @_;
    my $state = eval { read_state($runtime) };
    if ($@) {
        return {
            text    => '🎙',
            class   => 'error',
            tooltip => 'Whisper recorder state is unavailable',
        };
    }
    if ($state && process_matches_state($state)) {
        return {
            text    => '⏺ REC',
            class   => 'recording',
            tooltip => "Recording microphone to $state->{stem}.wav\nRight click, Super+R, or Ctrl+Alt+R to stop",
        };
    }
    return {
        text    => '🎙',
        class   => 'idle',
        tooltip => 'Whisper microphone recorder\nRight click, Super+R, or Ctrl+Alt+R to start',
    };
}

sub emit_status {
    my $payload;
    my $runtime = eval { runtime_directory() };
    if ($@) {
        $payload = {
            text    => '🎙',
            class   => 'error',
            tooltip => 'Whisper recorder is unavailable',
        };
    } else {
        my $lock = eval { open_runtime_lock($runtime, LOCK_SH) };
        if ($@) {
            $payload = {
                text    => '🎙',
                class   => 'error',
                tooltip => 'Whisper recorder state is unavailable',
            };
        } else {
            $payload = status_payload($runtime);
        }
    }
    print encode_json($payload), "\n";
}

sub main {
    @ARGV <= 1 or fatal('usage: whisper-record-toggle [start|stop|toggle|status]');
    my $action = $ARGV[0] // 'toggle';
    $action =~ /\A(?:start|stop|toggle|status)\z/
        or fatal('usage: whisper-record-toggle [start|stop|toggle|status]');

    if ($action eq 'status') {
        emit_status();
        return;
    }

    my $runtime = runtime_directory();
    my $home = home_directory();
    my $lock = open_runtime_lock($runtime, LOCK_EX);
    my $state = read_state($runtime);
    if ($action eq 'toggle') {
        if ($state && process_matches_state($state)) {
            stop_recording($runtime, $home);
        } else {
            clear_state($runtime) if $state;
            start_recording($runtime, $home);
        }
    } elsif ($action eq 'start') {
        start_recording($runtime, $home);
    } else {
        stop_recording($runtime, $home);
    }
}

main();

