   431	    kill 'TERM', $pid if process_matches_state($recording_state);
   432	    wait_for_recording_exit($recording_state);
   433	    eval {
   434	        set_default_audio_source_muted(1);
   435	        1;
   436	    };
   437	    die $error;
   438	}
