   449	sub normalize_transcript {
   450	    my ($text) = @_;
   451	    $text = q{} unless defined $text;
   452	    $text =~ s/[\p{Cc}\p{Cf}]+/ /gu;
   453	    $text =~ s/\s+/ /gu;
   454	    $text =~ s/\A\s+//u;
   455	    $text =~ s/\s+\z//u;
   456	    return $text;
   457	}
   458	
   459	sub transcript_from_whisper_json {
   460	    my ($data) = @_;
   461	    my @parts;
   462	    if (ref $data->{transcription} eq 'ARRAY') {
   463	        for my $segment (@{ $data->{transcription} }) {
   464	            next unless ref $segment eq 'HASH' && defined $segment->{text};
   465	            push @parts, $segment->{text};
   466	        }
   467	    } elsif (ref $data->{segments} eq 'ARRAY') {
   468	        for my $segment (@{ $data->{segments} }) {
   469	            next unless ref $segment eq 'HASH' && defined $segment->{text};
   470	            push @parts, $segment->{text};
   471	        }
   472	    } elsif (defined $data->{text}) {
   473	        push @parts, $data->{text};
   474	    } elsif (ref $data->{result} eq 'HASH' && defined $data->{result}{text}) {
   475	        push @parts, $data->{result}{text};
   476	    }
   477	    return normalize_transcript(join q{ }, @parts);
   478	}
