   480	sub append_todo_entry {
   481	    my ($sleek, $stem, $text) = @_;
   482	    return unless length $text;
   483	    my $lock_path = safe_child_path($sleek->{directory}, '.whisper.txt.lock');
   484	    sysopen my $lock, $lock_path, O_CREAT | O_RDWR, 0600
   485	        or fatal("cannot open Sleek task lock: $!");
   486	    flock($lock, LOCK_EX)
   487	        or fatal("cannot lock Sleek task file: $!");
   488	    open my $fh, '>>:encoding(UTF-8)', $sleek->{task_file}
   489	        or fatal("cannot append to Sleek task file: $!");
   490	    my $date = substr($stem, 0, 10);
   491	    print {$fh} "$date $text +whisper \@voice source:$stem\n"
   492	        or fatal("cannot write Sleek task entry: $!");
   493	    close $fh or fatal("cannot close Sleek task file: $!");
   494	}
