   496	sub prune_timestamped_files {
   497	    my ($directory, $extension) = @_;
   498	    opendir my $dh, $directory
   499	        or fatal("cannot read managed directory: $!");
   500	    my @files = grep {
   501	        /\A[0-9]{4}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}-[0-9]{2}\.\Q$extension\E\z/
   502	            && -f File::Spec->catfile($directory, $_)
   503	            && !-l File::Spec->catfile($directory, $_)
   504	    } readdir $dh;
   505	    closedir $dh or fatal("cannot close managed directory: $!");
   506	    @files = sort { $b cmp $a } @files;
   507	    for my $filename (@files[$MAX_ARTIFACTS .. $#files]) {
   508	        unlink safe_child_path($directory, $filename)
   509	            or fatal("cannot prune managed artifact $filename: $!");
   510	    }
   511	}
